import{_ as o,c as l,a2 as a,o as i}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第一千一百九十九章 精进等品 增支部1集61经到70经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1199第一千一百九十九章 精进等品 增支部1集61经到70经.md","filePath":"meditation/巴利文大藏经/1199第一千一百九十九章 精进等品 增支部1集61经到70经.md"}'),p={name:"meditation/巴利文大藏经/1199第一千一百九十九章 精进等品 增支部1集61经到70经.md"};function e(r,t,_,s,u,n){return i(),l("div",null,t[0]||(t[0]=[a('<h1 id="第一千一百九十九章-精进等品-增支部1集61经到70经" tabindex="-1">第一千一百九十九章 精进等品 增支部1集61经到70经 <a class="header-anchor" href="#第一千一百九十九章-精进等品-增支部1集61经到70经" aria-label="Permalink to &quot;第一千一百九十九章 精进等品 增支部1集61经到70经&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>增支部1集61经到70经</p><p>61经</p><ol start="61"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的善法生起，已生起的不善法衰减，如同这个，比丘们，即精进的开始。比丘们，对于已发起精进的人，未生起的善法生起，已生起的不善法衰减。&quot;这是第一经。</li></ol><p>62经</p><ol start="62"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的不善法生起，已生起的善法衰减，如同这个，比丘们，即大欲。比丘们，对于大欲的人，未生起的不善法生起，已生起的善法衰减。&quot;这是第二经。</li></ol><p>63经</p><ol start="63"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的善法生起，已生起的不善法衰减，如同这个，比丘们，即少欲。比丘们，对于少欲的人，未生起的善法生起，已生起的不善法衰减。&quot;这是第三经。</li></ol><p>64经</p><ol start="64"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的不善法生起，已生起的善法衰减，如同这个，比丘们，即不知足。比丘们，对于不知足的人，未生起的不善法生起，已生起的善法衰减。&quot;这是第四经。</li></ol><p>65经</p><ol start="65"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的善法生起，已生起的不善法衰减，如同这个，比丘们，即知足。比丘们，对于知足的人，未生起的善法生起，已生起的不善法衰减。&quot;这是第五经。</li></ol><p>66经</p><ol start="66"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的不善法生起，已生起的善法衰减，如同这个，比丘们，即非如理作意。比丘们，对于非如理作意的人，未生起的不善法生起，已生起的善法衰减。&quot;这是第六经。</li></ol><p>67经</p><ol start="67"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的善法生起，已生起的不善法衰减，如同这个，比丘们，即如理作意。比丘们，对于如理作意的人，未生起的善法生起，已生起的不善法衰减。&quot;这是第七经。</li></ol><p>68经</p><ol start="68"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的不善法生起，已生起的善法衰减，如同这个，比丘们，即不正知。比丘们，对于不正知的人，未生起的不善法生起，已生起的善法衰减。&quot;这是第八经。</li></ol><p>69经</p><ol start="69"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的善法生起，已生起的不善法衰减，如同这个，比丘们，即正知。比丘们，对于正知的人，未生起的善法生起，已生起的不善法衰减。&quot;这是第九经。</li></ol><p>70经</p><ol start="70"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的不善法生起，已生起的善法衰减，如同这个，比丘们，即恶友。比丘们，对于有恶友的人，未生起的不善法生起，已生起的善法衰减。&quot;这是第十经。</li></ol><p>精进等品第七完。</p>',24)]))}const c=o(p,[["render",e]]);export{d as __pageData,c as default};
